json_match = re.search(r'\{\s*"tables"', r)
if json_match:
    # Find the matching closing brace
    start = json_match.start()
    # Try to parse from this position
    try:
        data = json.loads(r[start:])
        print(f"Parsed! Tables: {list(data.get('tables', {}).keys())}")
        for tname, tinfo in data.get('tables', {}).items():
            print(f"  {tname}: {tinfo.get('count', '?')} rows")
    except json.JSONDecodeError:
        # Try to find end of JSON
        depth = 0
        for i, ch in enumerate(r[start:]):
            if ch == '{': depth += 1
            elif ch == '}': depth -= 1
            if depth == 0:
                try:
                    data = json.loads(r[start:start+i+1])
                    print(f"Parsed! Tables: {list(data.get('tables', {}).keys())}")
                    for tname, tinfo in data.get('tables', {}).items():
                        print(f"  {tname}: {tinfo.get('count', '?')} rows")
